{
  "name": "@renderxor/opencode-llamacpp-v2",
  "version": "1.0.4",
  "description": "Plugin llama.cpp router para OpenCode V2",
  "author": "renderxor",
  "license": "MIT",
  "type": "module",
  "exports": {
    ".": "./index.js",
    "./rpc": "./rpc.js",
    "./tui": "./tui.js"
  },
  "files": [
    "index.js",
    "rpc.js",
    "tui.js",
    "lib/",
    "README.md"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "llama.cpp",
    "llamacpp",
    "router"
  ],
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opencode/plugin": "2.3.2"
  },
  "scripts": {
    "test": "node --test test/*.test.js"
  }
}

import { createHash } from 'node:crypto';
import { Plugin, Model, Provider, Integration } from '@opencode/plugin';
import { normalizeBaseURL, routerModelsURL, parseRouterCatalog } from './lib/router.js';
import { CACHE_KEY, CACHE_VERSION, cacheKey, cachedCaps, isResident, parseCaps, presetFingerprint, propsURL, decodeCache, pruneCache } from './lib/reasoning.js';
import { pluginOptions } from './lib/options.js';
import { LlamacppRouter } from './rpc.js';

const PROVIDER_ID = 'llama.cpp';

function connectionKey(connection) {
  if (!connection) return null;
  return connection.type === 'credential' ? `credential:${connection.id}` : `env:${connection.name}`;
}

async function fetchCaps(baseURL, apiKey, modelId) {
  const response = await fetch(propsURL(baseURL, modelId), {
    method: 'GET',
    redirect: 'error',
    headers: { Accept: 'application/json', ...(apiKey ? { Authorization: `Bearer ${apiKey}` } : {}) },
    signal: AbortSignal.timeout(5000),
  });
  if (!response.ok) return null;
  return parseCaps(await response.json());
}

/**
 * Reads capabilities from resident instances only. `autoload=false` prevents the
 * router from loading a model just to discover its reasoning levels.
 */
async function enrichCaps(payload, baseURL, apiKey, cache, options) {
  if (!options.reasoning.enabled) return { caps: {}, entries: cache.entries, captured: [] };
  const entries = { ...cache.entries };
  const models = Array.isArray(payload?.data) ? payload.data : [];
  const resident = models.filter(raw => isResident(raw) && typeof raw.id === 'string');
  const captured = [];
  await Promise.all(resident.map(async raw => {
    try {
      const fresh = await fetchCaps(baseURL, apiKey, raw.id);
      if (!fresh) return;
      const key = cacheKey(baseURL, raw.id);
      const fingerprint = presetFingerprint(raw);
      const previous = entries[key];
      const unchanged = previous
        && previous.fingerprint === fingerprint
        && previous.supports === fresh.supports
        && previous.build === fresh.build
        && JSON.stringify(previous.levels) === JSON.stringify(fresh.levels)
        && JSON.stringify(previous.rejected) === JSON.stringify(fresh.rejected);
      entries[key] = {
        ...fresh,
        fingerprint,
        capturedAt: unchanged ? previous.capturedAt : Date.now(),
      };
      captured.push(raw.id);
    } catch { /* Capability discovery is optional and must not break the catalog. */ }
  }));
  const caps = {};
  for (const raw of models) {
    if (typeof raw?.id !== 'string') continue;
    const entry = cachedCaps(raw, baseURL, entries);
    if (entry) caps[raw.id] = entry;
  }
  return { caps, entries, captured };
}

async function fetchCatalog(baseURL, apiKey, options, cache) {
  const signal = AbortSignal.timeout(15000);
  const response = await fetch(routerModelsURL(baseURL), {
    method: 'GET',
    redirect: 'error',
    headers: { Accept: 'application/json', ...(apiKey ? { Authorization: `Bearer ${apiKey}` } : {}) },
    signal,
  });
  if (!response.ok) {
    const error = new Error(`GET /models: HTTP ${response.status}`);
    error.status = response.status;
    throw error;
  }
  const payload = await response.json();
  const { caps, entries, captured } = await enrichCaps(payload, baseURL, apiKey, cache, options);
  const catalog = parseRouterCatalog(payload, { ...options, caps });
  return { ...catalog, cache: { version: CACHE_VERSION, entries }, captured };
}

function makeProvider(snapshot) {
  const id = Provider.ID.make(PROVIDER_ID);
  const models = snapshot.catalog.map(spec => {
    const item = { ...Model.Info.default(id, Model.ID.make(spec.id)) };
    item.name = spec.name;
    item.limit = { context: spec.context, output: spec.output };
    item.capabilities = { ...spec.capabilities };
    item.variants = (spec.variants ?? []).map(variant => ({
      id: Model.VariantID.make(variant.id),
      ...(variant.settings ? { settings: variant.settings } : {}),
      ...(variant.headers ? { headers: variant.headers } : {}),
      ...(variant.body ? { body: variant.body } : {}),
    }));
    if (spec.compatibility) item.compatibility = spec.compatibility;
    return item;
  });
  return {
    info: {
      ...Provider.Info.empty(id),
      integrationID: Integration.ID.make(PROVIDER_ID),
      name: 'llama.cpp',
      activation: 'enabled',
      package: '@opencode/ai/providers/openai-compatible',
      // Only in process memory; /connect owns persistent credentials.
      settings: { baseURL: snapshot.baseURL, apiKey: snapshot.apiKey },
    },
    models,
    sourceConnection: snapshot.connection,
  };
}

export default Plugin.define({
  id: 'opencode-llamacpp-v2',
  async setup(ctx) {
    const options = pluginOptions(ctx.options);
    const state = {
      active: null,
      snapshot: null,
      signature: null,
      cache: decodeCache(undefined),
      cacheSignature: '',
      captured: new Set(),
    };
    let closing = false;

    if (options.reasoning.cache && ctx.storage) {
      try {
        state.cache = decodeCache(await ctx.storage.get(CACHE_KEY));
        state.cacheSignature = JSON.stringify(state.cache);
      } catch (error) {
        console.warn(`[opencode-llamacpp-v2] No se pudo leer la caché de razonamiento: ${error instanceof Error ? error.message : String(error)}`);
      }
    }

    const integrationReg = await ctx.integration.transform(editor => {
      editor.update(PROVIDER_ID, item => { item.name = 'llama.cpp'; });
      editor.method.update({
        integrationID: PROVIDER_ID,
        method: {
          type: 'key',
          label: 'Conectar servidor llama.cpp',
          form: [{
            key: 'baseURL',
            type: 'string',
            title: 'URL del servidor (con /v1 o sin él)',
            required: true,
            format: 'uri',
            placeholder: 'http://127.0.0.1:8080/v1',
          }],
        },
      });
    });

    const providerReg = await ctx.provider.transform(editor => {
      if (!state.snapshot) return;
      // Isolated account-specific source: OpenCode hides it after a connection switch.
      editor.add(makeProvider(state.snapshot));
    });

    const rpc = await ctx.rpc.register(LlamacppRouter, {});

    async function notify(payload) {
      try {
        await rpc.events.emit('toast', payload);
      } catch (error) {
        console.warn(`[opencode-llamacpp-v2] No se pudo mostrar el aviso de la TUI: ${error instanceof Error ? error.message : String(error)}`);
      }
    }

    async function persistCache(cache) {
      const bounded = { version: cache.version, entries: pruneCache(cache.entries) };
      state.cache = bounded;
      if (!options.reasoning.cache || !ctx.storage) return;
      const serialized = JSON.stringify(bounded);
      if (serialized === state.cacheSignature) return;
      state.cacheSignature = serialized;
      try {
        await ctx.storage.set(CACHE_KEY, bounded);
      } catch (error) {
        console.warn(`[opencode-llamacpp-v2] No se pudo guardar la caché de razonamiento: ${error instanceof Error ? error.message : String(error)}`);
      }
    }

    async function refresh() {
      if (closing) return { status: 'closing' };
      const connection = await ctx.integration.connection.active(PROVIDER_ID);
      const identity = connectionKey(connection);
      if (identity !== state.active) {
        state.active = identity;
        state.snapshot = null;
        state.signature = null;
        state.captured.clear();
        await ctx.provider.reload(); // Remove the previous account's catalog immediately.
      }
      if (!connection) return { status: 'no-connection' };

      const credential = await ctx.integration.connection.resolve(connection);
      if (credential?.type !== 'key') throw new Error('La conexión debe usar una API key');
      const meta = credential.metadata;
      const urlInput = typeof meta?.baseURL === 'string' ? meta.baseURL : undefined;
      if (!urlInput) throw new Error('Esta conexión no tiene URL; reconéctala mediante /connect');
      const baseURL = normalizeBaseURL(urlInput);
      let catalog;
      try {
        catalog = await fetchCatalog(baseURL, credential.key, options, state.cache);
      } catch (error) {
        if (error?.status === 401 || error?.status === 403) {
          try {
            await ctx.integration.connection.status({
              integrationID: PROVIDER_ID, connection,
              status: { status: 'needs_auth', message: 'API key rechazada por llama.cpp' },
            });
          } catch { /* Connection status is optional for the catalog. */ }
        }
        throw error;
      }
      const { models, skipped, cache, captured } = catalog;
      if (!models.length) throw new Error('No hay modelos de texto con contexto fijo verificable en /models');
      await persistCache(cache);

      // Prevent a slow response from overwriting a newly selected connection.
      const stillActive = await ctx.integration.connection.active(PROVIDER_ID);
      if (connectionKey(stillActive) !== identity || closing) return { status: 'stale' };
      state.captured = new Set(captured);

      const keyHash = createHash('sha256').update(credential.key).digest('hex');
      const signature = JSON.stringify({ identity, baseURL, keyHash, models });
      if (signature !== state.signature) {
        state.snapshot = { connection, baseURL, apiKey: credential.key, catalog: models };
        state.signature = signature;
        await ctx.provider.reload();
      }
      try {
        await ctx.integration.connection.status({
          integrationID: PROVIDER_ID, connection, status: undefined,
        });
      } catch { /* Not fatal for catalog updates. */ }
      console.info(`[opencode-llamacpp-v2] ${models.length} modelos registrados; ${skipped.length} omitidos`);
      for (const message of skipped) console.warn(`[opencode-llamacpp-v2] ${message}`);
      return { status: 'ok', models: models.length, skipped: skipped.length };
    }

    let queue = Promise.resolve();
    let pending = null;
    function scheduleRefresh() {
      if (pending) return pending;
      const task = queue.then(refresh);
      queue = task.catch(error => {
        console.warn(`[opencode-llamacpp-v2] Error de actualización: ${error instanceof Error ? error.message : String(error)}`);
      });
      pending = task.finally(() => { pending = null; });
      return pending;
    }

    const commandReg = await ctx.command.transform(editor => {
      editor.add({
        name: 'llamacpp-refresh',
        description: 'Actualizar modelos y contextos del servidor llama.cpp',
        execute: async () => {
          try {
            const result = await scheduleRefresh();
            if (result?.status === 'no-connection') {
              await notify({
                title: 'llama.cpp',
                message: 'No hay una conexión activa; usa /connect → llama.cpp',
                variant: 'warning',
                duration: 5000,
              });
              return;
            }
            if (result?.status !== 'ok') return;
            const omitted = result.skipped ? `; ${result.skipped} omitidos` : '';
            await notify({
              title: 'llama.cpp',
              message: `Catálogo actualizado: ${result.models} modelos${omitted}`,
              variant: result.skipped ? 'warning' : 'success',
              duration: 4000,
            });
          } catch (error) {
            await notify({
              title: 'llama.cpp',
              message: `Error al actualizar: ${error instanceof Error ? error.message : String(error)}`,
              variant: 'error',
              duration: 6000,
            });
          }
        },
      });
    });

    // Observe credentials, account switches and llama.cpp steps. The first token
    // means the router has loaded the model, so /props can finally report its levels.
    const controller = new AbortController();
    const sessionModels = new Map();
    void (async () => {
      try {
        for await (const event of ctx.event.subscribe({
          types: [
            'credential.updated',
            'credential.switched',
            'session.model.selected',
            'session.step.started',
            'session.step.first-token',
            'session.deleted',
          ],
          signal: controller.signal,
        })) {
          if (closing) break;
          const detail = event.data ?? event.properties;
          if (event.type === 'session.model.selected' || event.type === 'session.step.started') {
            const sessionID = detail?.sessionID;
            const model = detail?.model;
            if (sessionID && model?.providerID === PROVIDER_ID) sessionModels.set(sessionID, model.id);
            else if (sessionID) sessionModels.delete(sessionID);
            if (event.type === 'session.model.selected' && model?.providerID === PROVIDER_ID) {
              await scheduleRefresh().catch(() => {});
            }
            continue;
          }
          if (event.type === 'session.step.first-token') {
            if (!options.reasoning.enabled) continue;
            const modelId = detail?.sessionID ? sessionModels.get(detail.sessionID) : undefined;
            if (modelId && !state.captured.has(modelId)) {
              await scheduleRefresh().catch(() => {});
            }
            continue;
          }
          if (event.type === 'session.deleted') {
            if (detail?.sessionID) sessionModels.delete(detail.sessionID);
            continue;
          }
          if (detail?.integrationID && detail.integrationID !== PROVIDER_ID) continue;
          await scheduleRefresh().catch(() => {});
        }
      } catch (error) {
        if (!controller.signal.aborted)
          console.warn(`[opencode-llamacpp-v2] Suscripción a eventos: ${String(error)}`);
      }
    })();

    const timer = options.interval
      ? setInterval(() => { void scheduleRefresh().catch(() => {}); }, options.interval)
      : undefined;
    await ctx.integration.reload();
    await scheduleRefresh().catch(() => {});
    return async () => {
      closing = true;
      controller.abort();
      if (timer) clearInterval(timer);
      await Promise.allSettled([integrationReg.dispose(), providerReg.dispose(), commandReg.dispose(), rpc.dispose()]);
    };
  },
});
